(() => {
  const root=window.TitanWorkCore=window.TitanWorkCore||{},DB=()=>root.db,S=()=>root.contracts.stores,now=()=>new Date().toISOString(),activeRefreshes=new Map();
  const emit=(name,detail={})=>window.dispatchEvent(new CustomEvent(name,{detail}));
  function cancelRefresh(id){const c=activeRefreshes.get(id);if(!c)return false;c.abort();return true;}
  async function create(spec={}){const id=spec.id||crypto.randomUUID(),row={id,type:spec.type||'custom',name:spec.name||'Offline pack',version:Number(spec.version||1),record_ids:spec.record_ids||[],record_types:spec.record_types||[],include_recent_conversations:Boolean(spec.include_recent_conversations),customer_ids:spec.customer_ids||[],assigned_work:Boolean(spec.assigned_work),attachment_ids:spec.attachment_ids||[],knowledge_article_ids:spec.knowledge_article_ids||[],category_ids:spec.category_ids||[],status:'preparing',downloaded_items:0,total_items:0,last_refresh:null,expires_at:spec.expires_at||null,retention:spec.retention||'manual',pinned:Boolean(spec.pinned),storage_footprint:0,error:null,created_at:now(),updated_at:now()};await DB().put(S().offlinePacks,row);return refresh(id,spec);}
  async function estimateRequiredBytes(pack){let bytes=0;for(const id of pack.attachment_ids||[]){if(await DB().get(S().attachments,String(id)))continue;try{const r=await fetch(`${root.contracts.endpoints.attachments}/${encodeURIComponent(id)}`,{method:'HEAD',credentials:'same-origin',cache:'no-store'});bytes+=Number(r.headers.get('Content-Length')||0);}catch(_){}}return bytes;}
  async function downloadRecords(pack,signal){const url=new URL(root.contracts.endpoints.offlinePackRecords,location.origin);for(const id of pack.record_ids||[])url.searchParams.append('record_ids[]',id);for(const type of pack.record_types||[])url.searchParams.append('record_types[]',type);for(const id of pack.customer_ids||[])url.searchParams.append('customer_ids[]',id);if(pack.include_recent_conversations)url.searchParams.set('recent_conversations','1');if(pack.assigned_work)url.searchParams.set('assigned_work','1');const response=await fetch(url,{credentials:'same-origin',cache:'no-store',signal,headers:root.network?.requestHeaders({Accept:'application/json'})||{Accept:'application/json'}});if(!response.ok)throw new Error(`Offline record download failed (${response.status})`);const payload=await response.json();let count=0;for(const item of payload.records||payload.data||[]){const entityType=String(item.entity_type||item.type||'record'),id=String(item.id||item.uuid),key=`${entityType}:${id}`,existing=await DB().get(S().offlinePackRecords,key),packIds=new Set([...(existing?.pack_ids||[]),pack.id]);await DB().put(S().offlinePackRecords,{key,id,entity_type:entityType,pack_id:pack.id,pack_ids:[...packIds],payload:item,version:Number(item.version||1),updated_at:item.updated_at||now(),cached_at:now()});count++;}return count;}
  async function refresh(id,options={}){let pack=await DB().get(S().offlinePacks,id);if(!pack)throw new Error('Offline pack not found.');const controller=options.controller||new AbortController();activeRefreshes.set(id,controller);pack.status='downloading';pack.error=null;pack.updated_at=now();await DB().put(S().offlinePacks,pack);try{const required=await estimateRequiredBytes(pack),capacity=await root.storageManager.ensureCapacity(required);if(!capacity.ok&&!options.force)throw new Error(`Insufficient device storage for offline pack (${required} bytes required).`);await root.network?.waitForTransferPermission(required,{signal:controller.signal});const recordWork=(pack.record_ids?.length||pack.record_types?.length||pack.customer_ids?.length||pack.include_recent_conversations||pack.assigned_work)?1:0;let completed=0,total=recordWork+(pack.knowledge_article_ids?.length||0)+(pack.category_ids?.length||0)+(pack.attachment_ids?.length||0);pack.total_items=total;pack.downloaded_items=0;await DB().put(S().offlinePacks,pack);if(recordWork){await downloadRecords(pack,controller.signal);completed++;pack.downloaded_items=completed;await DB().put(S().offlinePacks,pack);emit('workcore:offline-pack-progress',{id,completed,total});}if(pack.knowledge_article_ids.length||pack.category_ids.length){await root.knowledge.downloadAll({articleIds:pack.knowledge_article_ids,categoryIds:pack.category_ids,signal:controller.signal});completed+=pack.knowledge_article_ids.length+pack.category_ids.length;pack.downloaded_items=completed;await DB().put(S().offlinePacks,pack);}for(const attachmentId of pack.attachment_ids){await root.network?.waitForTransferPermission(0,{signal:controller.signal});const key=String(attachmentId),found=await root.attachments.get(key);if(!found){const response=await fetch(`${root.contracts.endpoints.attachments}/${encodeURIComponent(key)}`,{credentials:'same-origin',signal:controller.signal,cache:'no-store',headers:root.network?.requestHeaders({})||{}});if(!response.ok)throw new Error(`Attachment download failed (${response.status})`);await root.attachments.save(await response.blob(),{id:key,pack_id:id,name:response.headers.get('X-Filename')||key,allow_duplicate:true});}else{const record=found.record,packIds=new Set([...(record.pack_ids||[]),record.pack_id,id].filter(Boolean).map(String));record.pack_ids=[...packIds];record.pack_id=record.pack_id||id;record.updated_at=now();await DB().put(S().attachments,record);}completed++;pack.downloaded_items=completed;await DB().put(S().offlinePacks,pack);emit('workcore:offline-pack-progress',{id,completed,total});}const attachments=(await DB().all(S().attachments)).filter(a=>(a.pack_ids||[]).includes(id)||a.pack_id===id||pack.attachment_ids.includes(a.id)),records=await DB().byIndex(S().offlinePackRecords,'by_pack',id);pack.storage_footprint=attachments.reduce((n,a)=>n+(a.size||0),0)+new Blob([JSON.stringify(records)]).size;pack.status='ready';pack.downloaded_items=total;pack.last_refresh=now();pack.updated_at=now();await DB().put(S().offlinePacks,pack);emit('workcore:offline-pack-ready',{pack});return pack;}catch(error){pack.status=error.name==='AbortError'?'paused':'failed';pack.error=error.message;pack.updated_at=now();await DB().put(S().offlinePacks,pack);emit('workcore:offline-pack-failed',{pack,error:error.message});throw error;}finally{activeRefreshes.delete(id);}}
  async function remove(id){const pack=await DB().get(S().offlinePacks,id);if(!pack)return false;for(const row of await DB().all(S().attachments)){if(!(row.pack_ids||[]).includes(id)&&row.pack_id!==id)continue;const remaining=(row.pack_ids||[]).filter(x=>String(x)!==String(id));row.pack_ids=remaining;if(String(row.pack_id)===String(id))row.pack_id=remaining[0]||null;if(!remaining.length&&!row.pack_id&&row.state==='synced'&&!row.pinned)await root.attachments.remove(row.id,{force:true});else await DB().put(S().attachments,row);}for(const row of await DB().all(S().offlinePackRecords)){if(!(row.pack_ids||[]).includes(id)&&row.pack_id!==id)continue;const remaining=(row.pack_ids||[]).filter(x=>String(x)!==String(id));if(!remaining.length)await DB().remove(S().offlinePackRecords,row.key);else{row.pack_ids=remaining;row.pack_id=remaining[0];await DB().put(S().offlinePackRecords,row);}}await DB().remove(S().offlinePacks,id);emit('workcore:offline-pack-removed',{id});return true;}
  async function pin(id,value=true){const pack=await DB().get(S().offlinePacks,id);if(!pack)return null;pack.pinned=value;pack.updated_at=now();await DB().put(S().offlinePacks,pack);return pack;}
  async function expired(){const current=Date.now();return(await DB().all(S().offlinePacks)).filter(p=>p.expires_at&&new Date(p.expires_at).getTime()<current&&!p.pinned);}
  root.offlinePacks={create,refresh,cancelRefresh,remove,pin,expired,downloadRecords,estimateRequiredBytes,all:()=>DB().all(S().offlinePacks),records:id=>DB().byIndex(S().offlinePackRecords,'by_pack',id)};
})();
